// ═══ ForkJoinPool: divide-and-conquer ═══
class SumTask extends RecursiveTask<Long> {
    private final long[] array;
    private final int start, end;
    private static final int THRESHOLD = 10_000;

    SumTask(long[] array, int start, int end) {
        this.array = array; this.start = start; this.end = end;
    }

    @Override
    protected Long compute() {
        if (end - start <= THRESHOLD) {
            // Base case: small enough → compute directly
            long sum = 0;
            for (int i = start; i < end; i++) sum += array[i];
            return sum;
        }
        // FORK: split into two subtasks
        int mid = (start + end) / 2;
        SumTask left = new SumTask(array, start, mid);
        SumTask right = new SumTask(array, mid, end);
        left.fork();  // submit left to pool (async!)
        long rightResult = right.compute();  // compute right in current thread
        long leftResult = left.join();  // JOIN: wait for left's result
        return leftResult + rightResult;
    }
}

ForkJoinPool pool = new ForkJoinPool(4);  // 4 workers
long sum = pool.invoke(new SumTask(array, 0, array.length));
// Splits recursively → each piece processed in parallel → results merged!

// ═══ WORK-STEALING ═══
// Worker-1 deque: [task-A][task-B][task-C]  ← works from TOP
// Worker-2 deque: [task-D]                   ← finishes quickly
// Worker-2 STEALS from Worker-1's BOTTOM:
// Worker-1 deque: [task-A][task-B]  (task-C stolen!)
// Worker-2 deque: [task-C]          (stolen, now busy!)
// Minimal contention: owner works from top, thief steals from bottom!

// ═══ commonPool ═══
ForkJoinPool common = ForkJoinPool.commonPool();
// Parallelism: Runtime.availableProcessors() - 1
// Shared by: parallelStream(), CompletableFuture.supplyAsync()
// Designed for: short CPU-bound tasks
// NOT for: blocking IO (use dedicated pool!)

// ═══ parallelStream uses ForkJoinPool! ═══
long sum2 = LongStream.range(0, 1_000_000)
    .parallel()  // uses ForkJoinPool.commonPool()!
    .map(x -> x * x)
    .sum();
// Internally: splits stream → ForkJoinPool workers process chunks → merge
