// ─── File: src/test/java/com/bank/forkjoin/ForkJoinPoolTest.java ───
package com.bank.forkjoin;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class ForkJoinPoolTest {

    // RecursiveTask: returns a result
    static class ArraySumTask extends RecursiveTask<Long> {
        private final long[] arr;
        private final int start, end;
        private static final int THRESHOLD = 1000;

        ArraySumTask(long[] arr, int start, int end) {
            this.arr = arr; this.start = start; this.end = end;
        }

        @Override
        protected Long compute() {
            if (end - start <= THRESHOLD) {
                long sum = 0;
                for (int i = start; i < end; i++) sum += arr[i];
                return sum;
            }
            int mid = (start + end) / 2;
            ArraySumTask left = new ArraySumTask(arr, start, mid);
            ArraySumTask right = new ArraySumTask(arr, mid, end);
            left.fork();
            long rightResult = right.compute();
            long leftResult = left.join();
            return leftResult + rightResult;
        }
    }

    // ═══ ForkJoinPool with RecursiveTask ═══
    @Test
    void forkJoin_parallelSum() {
        long[] arr = LongStream.range(0, 100_000).toArray();
        long expected = LongStream.range(0, 100_000).sum();

        ForkJoinPool pool = new ForkJoinPool(4);
        long result = pool.invoke(new ArraySumTask(arr, 0, arr.length));

        assertThat(result).isEqualTo(expected);
        pool.shutdown();
    }

    // ═══ commonPool info ═══
    @Test
    void commonPool_info() {
        ForkJoinPool common = ForkJoinPool.commonPool();
        int parallelism = common.getParallelism();
        int cores = Runtime.getRuntime().availableProcessors();

        System.out.println("Cores: " + cores + ", commonPool parallelism: " + parallelism);
        assertThat(parallelism).isLessThanOrEqualTo(cores);
    }

    // ═══ parallelStream uses ForkJoinPool ═══
    @Test
    void parallelStream_usesFJP() {
        long sum = LongStream.range(0, 100_000)
            .parallel()
            .map(x -> x * x)
            .sum();

        assertThat(sum).isGreaterThan(0);
    }

    // ═══ Custom ForkJoinPool for parallelStream ═══
    @Test
    void customPool_forParallelStream() throws Exception {
        ForkJoinPool custom = new ForkJoinPool(2);

        long sum = custom.submit(() ->
            LongStream.range(0, 100_000)
                .parallel()  // runs on CUSTOM pool, not commonPool!
                .map(x -> x * x)
                .sum()
        ).get();

        assertThat(sum).isGreaterThan(0);
        custom.shutdown();
    }
}
